"use strict";

// Copy helper for card IDs.
//
// A card ID is the 32-char hex uuid generated by the server. Users quote it
// when they refer to a card, so the UI must let them copy it exactly.
//
// This file holds only the DOM-independent logic, so the Node tests in
// tests/test_cardid_js.js can exercise the real code instead of a copy of it.
// main.js loads this as a global (`CardId`) before it runs.
(function (root) {
  // Return a plain, trimmed ID string, or "" when there is nothing to copy.
  function normalize(id) {
    if (typeof id !== "string") return "";
    return id.trim();
  }

  // Copy through the legacy `execCommand("copy")` path, used when the async
  // Clipboard API is missing (insecure origin) or rejects (denied permission).
  // The textarea must be visible to the layout for select() to work, so it is
  // moved off-screen instead of being hidden with `display: none`.
  function legacyCopy(doc, text) {
    const area = doc.createElement("textarea");
    area.value = text;
    area.setAttribute("readonly", "");
    area.style.position = "fixed";
    area.style.top = "-1000px";
    area.style.opacity = "0";
    doc.body.appendChild(area);
    let copied = false;
    try {
      area.select();
      copied = doc.execCommand("copy") === true;
    } catch (err) {
      copied = false;
    }
    doc.body.removeChild(area);
    return copied;
  }

  // Copy `text` to the clipboard, reporting success as a boolean. Never
  // rejects: a failed copy returns false so callers can show a hint.
  async function copyText(text, nav, doc) {
    const value = normalize(text);
    if (!value) return false;
    if (nav && nav.clipboard && typeof nav.clipboard.writeText === "function") {
      try {
        await nav.clipboard.writeText(value);
        return true;
      } catch (err) {
        // Permission denied or a non-secure context: try the legacy path.
      }
    }
    if (doc && typeof doc.execCommand === "function") {
      return legacyCopy(doc, value);
    }
    return false;
  }

  const api = { normalize: normalize, legacyCopy: legacyCopy, copyText: copyText };

  if (typeof module !== "undefined" && module.exports) {
    module.exports = api;
  } else {
    root.CardId = api;
  }
})(typeof window !== "undefined" ? window : globalThis);
